package org.apache.commons.compress.utils;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.DataOutput;
import java.io.DataOutputStream;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class ByteUtils_ESTest_test02 extends ByteUtils_ESTest_scaffolding {

    /**
     * Writing the value 50 to a DataOutput as a 212-byte little-endian sequence
     * should emit 50 as the first (lowest) byte and zero for the remaining 211 bytes.
     */
    @Test(timeout = 4000)
    public void toLittleEndian_writesValueAsFirstByteAndZeroPadsTheRest() throws Throwable {
        final long valueToWrite = 50L;
        final int totalBytes = 212;

        ByteArrayOutputStream capturedBytes = new ByteArrayOutputStream();
        DataOutput dataOutput = new DataOutputStream(capturedBytes);

        ByteUtils.toLittleEndian(dataOutput, valueToWrite, totalBytes);

        // The full requested length is written out.
        assertEquals(totalBytes, capturedBytes.size());

        // First byte holds the value ('2' == 50); the remaining 211 bytes are zero (NUL).
        StringBuilder expectedOutput = new StringBuilder();
        expectedOutput.append((char) valueToWrite);
        char[] zeroPadding = new char[totalBytes - 1]; // char[] defaults to '�'
        expectedOutput.append(zeroPadding);
        assertEquals(expectedOutput.toString(), capturedBytes.toString());
    }
}
